// Defensive: the agent may wrap text in fences or add prose.
const raw = String($json.response ?? '');
const secret = 'AURORA';
return [{
  json: {
    step: 'store',
    pass: raw.toUpperCase().includes(secret),
    expected: `text containing ${secret}`,
    sessionSource: $json.sessionSource,
    memoryArn: $json.harness?.memory?.arn ?? null,
    harnessVersion: $json.harness?.version ?? null,
    response: raw.slice(0, 400),
  },
}];

// PASS = actor A gets the codename back in a separate execution.
const raw = String($json.response ?? '').trim();
const secret = 'AURORA';
const recalled = raw.toUpperCase().includes(secret);

// Distinguish a real failure from a transient service error, which returns no
// text at all. An empty response proves nothing either way.
const inconclusive = raw === '';

let note;
if (recalled) {
  note = 'Cross-execution recall confirmed.';
} else if (inconclusive) {
  note = 'INCONCLUSIVE: empty response (likely a transient service error). Re-run this step.';
} else {
  note = 'FAIL: actor A did not recall the stored codename. Check that Session ID and Actor ID match step 1 and that Memory Mode is Managed.';
}

return [{
  json: {
    step: 'recall',
    claim: 'memory persists across separate executions',
    pass: recalled,
    inconclusive,
    sessionSource: $json.sessionSource,
    note,
    response: raw.slice(0, 400),
  },
}];

// PASS = actor B must NOT see actor A's codename.
// Check the whole payload, not just the prose, so a tool trace cannot hide a leak.
const secret = 'AURORA';
const raw = String($json.response ?? '').trim();
const everything = JSON.stringify($json).toUpperCase();
const leaked = everything.includes(secret);

// An empty response means the service returned a transient error. That is NOT
// evidence of isolation - it is no evidence at all. Report it as inconclusive
// so a failed call can never be mistaken for a pass.
const inconclusive = raw === '';

let verdict;
if (leaked) {
  verdict = 'FAIL: actor B saw actor A memory. Do not ship per-user memory templates.';
} else if (inconclusive) {
  verdict = 'INCONCLUSIVE: empty response (likely a transient service error). Re-run this step.';
} else {
  verdict = 'PASS: actor B did not receive actor A memory.';
}

return [{
  json: {
    step: 'isolation',
    claim: "one actor's memory never reaches another",
    pass: !leaked && !inconclusive,
    leaked,
    inconclusive,
    verdict,
    response: raw.slice(0, 400),
  },
}];
